package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import org.json.*;import java.io.*;
/** Shared transparent atlases; source cells and doorway anchors are explicit data. */
final class BaseSpriteAtlas {
 static Bitmap houses,annexes;static JSONObject index;static int sample;private final Paint paint=new Paint();
 BaseSpriteAtlas(Context c,int quality){int wanted=quality==0?2:1;synchronized(BaseSpriteAtlas.class){if(houses!=null&&annexes!=null&&index!=null&&sample==wanted)return;try{BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=wanted;options.inPreferredConfig=Bitmap.Config.ARGB_8888;try(InputStream in=c.getAssets().open("base-houses-v090-final.png")){houses=BitmapFactory.decodeStream(in,null,options);}try(InputStream in=c.getAssets().open("base-outbuildings-v090-final.png")){annexes=BitmapFactory.decodeStream(in,null,options);}try(InputStream in=c.getAssets().open("base-sprite-index.json")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)bytes.write(buffer,0,n);index=new JSONObject(bytes.toString("UTF-8"));}sample=wanted;}catch(Exception ignored){houses=null;annexes=null;index=null;}}}
 boolean draw(Canvas canvas,JSONObject building,boolean obstructs){if(index==null)return false;String id=building.optString("id"),style=building.optString("houseDesign");JSONObject cell=null;Bitmap atlas=null;
  if(id.startsWith("annex:")){String[] parts=id.split(":");JSONObject entries=index.optJSONObject("annexes");if(parts.length>1&&entries!=null)cell=entries.optJSONObject(parts[1]);atlas=annexes;}
  else if(id.startsWith("home:")||!style.isEmpty()){if(style.isEmpty()){String[] parts=id.split(":");if(parts.length>1)style=parts[1];}JSONObject entries=index.optJSONObject("houses");JSONArray levels=entries==null?null:entries.optJSONArray(style);if(levels!=null)cell=levels.optJSONObject(Math.max(0,Math.min(7,building.optInt("baseLevel",1)-1)));atlas=houses;}
  if(cell==null||atlas==null)return false;float sx=atlas.getWidth()/(float)index.optInt("width",1774),sy=atlas.getHeight()/(float)index.optInt("height",887);int left=Math.round(cell.optInt("x")*sx),top=Math.round(cell.optInt("y")*sy),right=Math.round((cell.optInt("x")+cell.optInt("w"))*sx),bottom=Math.round((cell.optInt("y")+cell.optInt("h"))*sy);if(right<=left||bottom<=top)return false;
  float width=(float)(building.optDouble("halfWidth",90)*2+building.optDouble("depth",80)+16),height=width*(bottom-top)/(right-left),ax=(float)cell.optDouble("anchorX",.7),ay=(float)cell.optDouble("anchorY",.92);JSONObject door=building.optJSONObject("door");float dx=door==null?0:(float)(door.optDouble("x")-building.optDouble("x")),dy=door==null?35:(float)(door.optDouble("y")-building.optDouble("y"));canvas.save();canvas.translate(dx-dy,(dx+dy)*.5f);int rotation=building.optInt("rotation");if(rotation==90||rotation==180)canvas.scale(-1,1);paint.setColor(Color.WHITE);paint.setAlpha(obstructs?110:255);canvas.drawBitmap(atlas,new Rect(left,top,right,bottom),new RectF(-width*ax,-height*ay,width*(1-ax),height*(1-ay)),paint);paint.setAlpha(255);canvas.restore();return true;
 }
}
